class Solution:
    def networkBecomesIdle(self, edges: List[List[int]], patience: List[int]) -> int:
        from collections import deque
        n = len(patience)
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        def dist_to_master(src):
            dist = [-1] * n
            dist[src] = 0
            q = deque([src])
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        q.append(v)
            return dist[0]

        ans = 0
        for i in range(1, n):
            rt = 2 * dist_to_master(i)
            last = (rt - 1) // patience[i] * patience[i]
            ans = max(ans, last + rt)
        return ans + 1

