class Solution {
    public int networkBecomesIdle(int[][] edges, int[] patience) {
        int n = patience.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int ans = 0;
        for (int src = 1; src < n; src++) {
            int[] dist = new int[n];
            Arrays.fill(dist, -1);
            Queue<Integer> q = new ArrayDeque<>();
            dist[src] = 0;
            q.offer(src);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : adj.get(u))
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        q.offer(v);
                    }
            }
            int rt = 2 * dist[0];
            int last = (rt - 1) / patience[src] * patience[src];
            ans = Math.max(ans, last + rt);
        }
        return ans + 1;
    }
};

