var networkBecomesIdle = function(edges, patience) {
    const n = patience.length;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const bfsDist = src => {
        const dist = new Array(n).fill(-1);
        dist[src] = 0;
        const q = [src];
        for (let h = 0; h < q.length; h++) {
            const u = q[h];
            for (const v of adj[u])
                if (dist[v] === -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
        }
        return dist[0];
    };
    let ans = 0;
    for (let i = 1; i < n; i++) {
        const rt = 2 * bfsDist(i);
        const last = Math.floor((rt - 1) / patience[i]) * patience[i];
        ans = Math.max(ans, last + rt);
    }
    return ans + 1;
};

